task.vi:
Một định nghĩa lớp Time có chứa cả hai hàm tạo sau có thể được dùng để khởi tạo mặc định một đối tượng Time không:
Time(int h = 0, int m = 0, int s = 0);
Time();
Nếu không, hãy giải thích nguyên nhân gây lỗi của trình biên dịch.

example.code:
#include <iostream>
#include <iomanip>

class Time {
private:
    int totalSeconds{0}; // Seconds since midnight: [0, 86399]

public:
    Time() = default;

    Time(int h, int m, int s) {
        if (!setTime(h, m, s)) {
            totalSeconds = 0;
        }
    }

    bool setHour(int h) {
        if (h >= 0 && h < 24) {
            totalSeconds = (h * 3600) + (getMinute() * 60) + getSecond();
            return true;
        }
        return false;
    }

    bool setMinute(int m) {
        if (m >= 0 && m < 60) {
            totalSeconds = (getHour() * 3600) + (m * 60) + getSecond();
            return true;
        }
        return false;
    }

    bool setSecond(int s) {
        if (s >= 0 && s < 60) {
            totalSeconds = (getHour() * 3600) + (getMinute() * 60) + s;
            return true;
        }
        return false;
    }

    bool setTime(int h, int m, int s) {
        if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
            totalSeconds = (h * 3600) + (m * 60) + s;
            return true;
        }
        return false;
    }

    int getHour() const { return totalSeconds / 3600; }
    int getMinute() const { return (totalSeconds % 3600) / 60; }
    int getSecond() const { return totalSeconds % 60; }

    void tick() {
        totalSeconds = (totalSeconds + 1) % 86400;
    }

    void printUniversal() const {
        std::cout << std::setfill('0')
                  << std::setw(2) << getHour() << ":"
                  << std::setw(2) << getMinute() << ":"
                  << std::setw(2) << getSecond() << "\n";
    }
};

int main() {
    Time t(23, 59, 58);
    std::cout << "Initial universal time: ";
    t.printUniversal();

    t.tick();
    std::cout << "After 1 tick: ";
    t.printUniversal();

    t.tick();
    std::cout << "After rollover: ";
    t.printUniversal();

    bool ok = t.setTime(25, 10, 10);
    std::cout << "Set invalid hour result: " << (ok ? "SUCCESS" : "FAILED") << "\n";
    return 0;
}

#include <iostream>
#include <vector>

class IntegerSet {
private:
    std::vector<bool> setTable;

public:
    IntegerSet() : setTable(101, false) {}

    void insertElement(int k) {
        if (k >= 0 && k <= 100) {
            setTable[k] = true;
        }
    }

    void deleteElement(int m) {
        if (m >= 0 && m <= 100) {
            setTable[m] = false;
        }
    }

    IntegerSet unionOfSets(const IntegerSet& other) const {
        IntegerSet result;
        for (size_t i = 0; i <= 100; ++i) {
            result.setTable[i] = this->setTable[i] || other.setTable[i];
        }
        return result;
    }

    IntegerSet intersectionOfSets(const IntegerSet& other) const {
        IntegerSet result;
        for (size_t i = 0; i <= 100; ++i) {
            result.setTable[i] = this->setTable[i] && other.setTable[i];
        }
        return result;
    }

    void printSet() const {
        bool empty = true;
        for (int i = 0; i <= 100; ++i) {
            if (setTable[i]) {
                std::cout << i << " ";
                empty = false;
            }
        }
        if (empty) {
            std::cout << "---";
        }
        std::cout << "\n";
    }
};

int main() {
    IntegerSet setA;
    setA.insertElement(10);
    setA.insertElement(25);
    setA.insertElement(50);

    IntegerSet setB;
    setB.insertElement(25);
    setB.insertElement(75);

    std::cout << "Set A: ";
    setA.printSet();

    std::cout << "Set B: ";
    setB.printSet();

    IntegerSet setUnion = setA.unionOfSets(setB);
    std::cout << "Union of A and B: ";
    setUnion.printSet();

    IntegerSet setInter = setA.intersectionOfSets(setB);
    std::cout << "Intersection of A and B: ";
    setInter.printSet();

    return 0;
}
